// Generated by tools/build_pet_vocab.js from vocab_engine.html. Do not edit by hand.
window.PET_VOCAB = {"1":{"title":"Understanding Health & Wellness","terms":[["Health","A combination of physical, mental/emotional, and social well-being — not just the absence of disease."],["Wellness","The quality of life that results from taking positive steps toward achieving your full health potential."],["Health Triangle","A model showing the three sides of health: physical, mental/emotional, and social — all must be balanced."],["Lifestyle factors","Personal behaviors and habits that affect your long-term health, both positively and negatively."],["Health literacy","The ability to find, understand, evaluate, and apply health information to make responsible decisions."],["Heredity","The passing of traits from biological parents to their children through genes."],["Environment","All living and nonliving things around you, including your community, culture, and physical surroundings."],["Culture","The beliefs, values, and practices shared by a group of people — a major influence on health decisions."],["Peers","People of the same age who share similar interests; a powerful influence on teen health behavior."],["Risk behaviors","Actions or habits that increase the likelihood of negative outcomes to one's health or others."],["Prevention","Taking action to avoid disease, injury, and other health problems before they occur."],["Abstinence","The deliberate decision to refrain from a risky behavior."],["Health promotion","The process of enabling people to increase control over and improve their health."],["Protective factors","Conditions or attributes that reduce the impact of risk factors on health outcomes."],["Attitude","A feeling or disposition toward a person, object, or idea that influences behavior."]]},"2":{"title":"Skills for a Healthy Life","terms":[["Goal setting","The process of identifying something you want to accomplish and creating a plan to achieve it."],["SMART goals","Goals that are Specific, Measurable, Achievable, Realistic, and Time-bound."],["Decision making","A five-step process for making healthy, responsible choices."],["Values","The beliefs and principles that guide your behavior and decisions."],["Refusal skills","Strategies that help you say no to things that are harmful or illegal."],["Conflict resolution","A process for resolving disagreements in a peaceful, constructive way."],["Stress management","Techniques for controlling and reducing the physical and emotional effects of stress."],["Communication skills","The ability to share information clearly with others using listening, speaking, and body language."],["Self-management","The ability to control your emotions, behaviors, and actions to make healthy choices."],["Advocacy","Taking action to promote health and influence others to make positive choices."],["Accessing information","The skill of finding and evaluating reliable, accurate health information from valid sources."],["Analyzing influences","The ability to identify and examine the factors that affect health beliefs and behaviors."]]},"3":{"title":"Mental and Emotional Health","terms":[["Mental health","The state of your psychological and emotional well-being — how you think, feel, and cope with life."],["Emotions","Signals that tell your mind and body how to react to situations."],["Self-concept","The view you have of yourself — your strengths, weaknesses, thoughts, and feelings."],["Self-esteem","The confidence and satisfaction you have in yourself and your own abilities."],["Empathy","The ability to understand and share the feelings of another person."],["Emotional intelligence","The ability to recognize, understand, and manage your own emotions and recognize emotions in others."],["Resiliency","The ability to recover from setbacks, adapt to change, and keep going in the face of adversity."],["Grief","The emotional response to loss — a normal and necessary process that takes time."],["Coping strategies","Healthy ways of managing and reducing the emotional pain of difficult situations."],["Defense mechanisms","Unconscious mental strategies used to protect yourself from uncomfortable emotions."],["Positive affirmations","Statements that remind you of your strengths and help reinforce a positive self-image."],["Mindfulness","The practice of focusing attention on the present moment with openness and without judgment."]]},"4":{"title":"Managing Stress","terms":[["Stress","The body's and mind's reaction to everyday demands and threats, real or perceived."],["Stressor","Any situation, event, or person that causes stress."],["Fight-or-flight response","The body's automatic physiological reaction to a perceived threat — prepares to fight or flee."],["Adrenaline","The hormone released during stress that increases heart rate, blood pressure, and energy."],["Eustress","Positive stress that motivates and energizes, such as excitement before a sports event."],["Distress","Negative stress that feels overwhelming and harmful to health."],["Chronic stress","Ongoing, long-term stress that persists over weeks or months and damages health."],["Relaxation response","The body's ability to slow down and recover after a stressful event."],["Time management","The practice of organizing and prioritizing tasks to reduce stress and increase productivity."],["Support network","Friends, family, and others who provide emotional encouragement and practical help."],["Burnout","A state of physical and emotional exhaustion from prolonged, unmanaged stress."],["Cortisol","The primary stress hormone; sustained high levels damage the immune system and cardiovascular health."]]},"5":{"title":"Mental and Emotional Problems","terms":[["Mental disorder","An illness that affects a person's thinking, feeling, or behavior significantly enough to cause distress."],["Anxiety disorder","A category of mental health conditions characterized by excessive, persistent fear or worry."],["Depression","A mood disorder marked by persistent sadness, hopelessness, loss of interest, and low energy."],["Suicide","The act of intentionally ending one's own life — a preventable public health crisis."],["Suicide prevention","Strategies and actions to recognize warning signs and connect people to help before a crisis."],["Eating disorder","A serious mental illness involving extreme disturbances in eating behavior and body image."],["Anorexia nervosa","An eating disorder involving severe restriction of food intake driven by fear of weight gain."],["Bulimia nervosa","An eating disorder involving cycles of binge eating followed by purging behaviors."],["PTSD","Post-Traumatic Stress Disorder — a mental health condition triggered by experiencing or witnessing trauma."],["Therapy","Treatment by a trained mental health professional using evidence-based psychological methods."],["Psychiatry","A branch of medicine focused on diagnosing, treating, and preventing mental disorders."],["Stigma","Negative attitudes or discrimination against people with mental health conditions — a major barrier to seeking help."]]},"6":{"title":"Building Healthy Relationships","terms":[["Relationship","A bond or connection between people based on shared experiences, trust, and mutual care."],["Communication","The process of sharing information, thoughts, and feelings using verbal and nonverbal methods."],["Active listening","Fully concentrating on what someone is saying, showing you understand, and responding thoughtfully."],["Assertiveness","The ability to express your thoughts and feelings confidently and respectfully, without aggression."],["Boundary","A limit you set to protect your physical, emotional, and mental well-being in relationships."],["Trust","The firm belief in the reliability, truth, or ability of another person — the foundation of healthy relationships."],["Respect","Treating others with consideration for their feelings, rights, and boundaries."],["Reciprocity","The mutual exchange of benefits, care, or support between people in a healthy relationship."],["Jealousy","A feeling of insecurity or fear of losing something or someone to another — can damage relationships."],["Healthy relationship","A relationship built on trust, respect, communication, equality, and support for each other's goals."]]},"7":{"title":"Family Relationships","terms":[["Siblings","Brothers and sisters."],["Nuclear family","Two parents and one or more children living in the same home."],["Blended family","A family formed when a single parent remarries, bringing together children from previous relationships."],["Extended family","A family that includes relatives beyond parents and children, such as grandparents, aunts, uncles and cousins."],["Foster care","The temporary placement of children in the homes of adults who are not related to them."],["Affirmation","Positive feedback that helps others feel appreciated and supported."],["Separation","A decision by two married people to live apart from each other."],["Divorce","A legal end to a marriage contract."],["Custody","The legal right to make decisions affecting children and the responsibility for their care."],["Abuse","The physical, mental, emotional, or sexual mistreatment of one person by another."],["Domestic violence","Acts of violence or abuse involving family members."],["Spousal abuse","Domestic violence or abuse directed at a spouse or partner."],["Child abuse","Domestic abuse directed at a child, including physical, emotional, or sexual harm."],["Neglect","The failure to provide for a child's basic needs."],["Elder abuse","The abuse or neglect of older family members."],["Cycle of violence","The pattern of repeating violent or abusive behaviors from one generation to the next."],["Crisis center","A facility that offers advice and support to people dealing with personal emergencies."]]},"8":{"title":"Peer Relationships","terms":[["Peers","People your age who share similar interests."],["Platonic friendship","A friendship with someone of a different gender involving genuine affection, but without romantic involvement."],["Clique","A small circle of friends who exclude people viewed as outsiders."],["Peer pressure","The influence that people your age may have on your actions and behaviors."],["Harassment","Persistently annoying or targeting others through hurtful behaviors like name-calling, teasing, or bullying."],["Manipulation","An indirect, dishonest way to control or influence other people."],["Refusal skills","Communication strategies that help you say no when urged to take part in unsafe or unhealthy behaviors."],["Priorities","The goals, tasks, values, and activities you judge to be most important."],["Intimacy","A closeness between two people that develops over time through genuine connection and trust."],["Infatuation","Exaggerated feelings of intense passion that can feel overwhelming but are often short-lived."],["Abstinence","A deliberate decision to avoid high-risk behaviors, including sexual activity and the use of alcohol, tobacco, and other drugs."],["Self-control","The ability to use responsibility and values to override emotions in the moment."],["Sexually transmitted infections (STIs)","Infectious diseases spread from person to person through sexual contact."]]},"9":{"title":"Resolving Conflicts and Preventing Violence","terms":[["Conflict","Any disagreement, struggle, or fight."],["Interpersonal conflicts","Conflicts between two or more people or groups."],["Escalate","To become more serious or intense."],["Negotiation","The use of communication and compromise to settle a disagreement."],["Mediation","Bringing in a neutral third party to help others resolve their conflicts peacefully."],["Confidentiality","Respecting the privacy of both parties and keeping details of a discussion secret."],["Peer mediation","A process in which specially trained students help other students resolve conflicts peacefully."],["Violence","The threatened or actual use of physical force or power to harm another person or damage property."],["Assault","An unlawful physical attack or threat of attack."],["Random violence","Violence committed for no particular reason against an unrelated victim."],["Homicide","The willful killing of one human being by another."],["Sexual violence","Any form of unwelcome sexual contact directed at an individual."],["Bullying","Repeated, deliberate hurtful behavior by someone who has more power than the target."],["Cyberbullying","Bullying that happens through phones, social media, games, or other technology."],["Physical abuse","A pattern of intentionally causing bodily harm or injury to another person."],["Emotional abuse","A pattern of attacking another person's emotional development and sense of worth."],["Verbal abuse","The use of words to mistreat or injure another person; a form of emotional abuse."],["Stalking","Repeatedly following, harassing, or threatening an individual in person or online."]]},"10":{"title":"Nutrition for Health","terms":[["Nutrients","Substances in food that provide energy and materials the body needs to grow, repair, and function."],["Carbohydrates","The body's primary energy source; should make up 45–65% of daily calories."],["Proteins","Nutrients that build and repair cells, muscles, and tissues; made of amino acids."],["Fats","Nutrients that store energy, protect organs, and support vitamin absorption; essential in moderation."],["Vitamins","Organic compounds needed in small amounts to regulate body functions and prevent disease."],["Minerals","Inorganic substances (calcium, iron, zinc) essential for bone health, blood, and body functions."],["MyPlate","The USDA visual guide showing the five food groups and recommended proportions for healthy eating."],["Calorie","A unit of energy; the amount of energy in food that the body uses to perform functions."],["Dietary fiber","Indigestible plant material that supports digestive health, lowers cholesterol, and controls blood sugar."],["Saturated fat","A type of fat found in animal products that raises LDL (bad) cholesterol when consumed in excess."],["Trans fat","An artificially created fat that raises bad cholesterol and lowers good cholesterol — largely banned."],["Nutrition label","The panel on food packaging showing calorie count, nutrients, and percent daily values."]]},"11":{"title":"Managing Weight","terms":[["Body Mass Index (BMI)","A ratio of weight to height used as a screening tool for healthy weight — not a diagnosis."],["Metabolism","The rate at which your body converts food into energy — affects weight management."],["Basal metabolic rate","The number of calories your body needs to maintain basic functions at rest."],["Caloric balance","The relationship between calories consumed and calories burned through activity."],["Body image","The way you see and feel about your physical appearance."],["Eating disorder","A serious mental illness with extreme disturbances in eating behavior, body image, and weight."],["Anorexia nervosa","An eating disorder involving extreme restriction of food intake driven by fear of weight gain."],["Bulimia nervosa","An eating disorder with cycles of binge eating followed by purging."],["Binge eating disorder","Recurrent episodes of eating large amounts of food rapidly without purging — most common ED."],["Fad diet","A popular diet promising quick weight loss that typically lacks scientific support and is unsustainable."],["Weight management","A long-term approach to maintaining a healthy weight through balanced nutrition and physical activity."],["Obesity","A condition of excess body fat that increases risk of diabetes, heart disease, and other conditions."]]},"12":{"title":"Physical Activity","terms":[["Physical activity","Any movement that uses energy — from walking to organized sports."],["Exercise","Planned, structured, repetitive physical activity done to improve or maintain fitness."],["Aerobic exercise","Sustained activity that increases heart and breathing rate — improves cardiovascular fitness."],["Anaerobic exercise","Short, intense bursts of activity that don't rely on oxygen — builds strength and power."],["Flexibility","The range of motion available at a joint — maintained through stretching."],["Muscle strength","The maximum force a muscle or muscle group can exert in a single effort."],["Muscle endurance","The ability of a muscle to perform repeated contractions over time without fatigue."],["Cardiovascular endurance","The ability of the heart and lungs to supply oxygen during sustained physical activity."],["FITT principle","Frequency, Intensity, Time, and Type — the four variables used to design an effective workout."],["Overload principle","To improve fitness, you must gradually increase the demand placed on the body."],["Warm-up","Low-intensity activity before exercise that prepares muscles and reduces injury risk."],["Cool-down","Low-intensity activity after exercise that gradually returns the body to its resting state."]]},"13":{"title":"Personal Health Care","terms":[["Epidermis","The outer, thinner layer of skin composed of living and dead cells."],["Dermis","The thicker inner layer of skin containing blood vessels, nerves, and glands."],["Melanin","The pigment that gives skin, hair, and eyes their color and provides some UV protection."],["Sebaceous glands","Structures in the dermis that produce sebum — an oily secretion that moisturizes skin and hair."],["Melanoma","The most serious and potentially fatal form of skin cancer — detected using the ABCDE rule."],["Periodontium","The structures immediately surrounding a tooth, including the gum, ligaments, and jawbone."],["Plaque","A sticky film of bacteria and food particles on teeth that produces acids causing decay."],["Halitosis","Bad breath caused by food, poor oral hygiene, bacteria, or gum disease."],["Periodontal disease","Inflammation and infection of the gum and supporting structures of the teeth."],["Sclera","The tough white outer layer of the eye."],["Retina","The inner layer of the eye containing light-sensitive rods and cones."],["Tinnitus","A ringing, buzzing, or hissing sound in the ear with no external source — warning sign of hearing damage."]]},"14":{"title":"Skeletal, Muscular & Nervous Systems","terms":[["Cartilage","Strong, flexible connective tissue that cushions joints and forms soft structures like the nose and ears."],["Ossification","The process by which cartilage is converted into bone during development."],["Ligament","A band of fibrous connective tissue that connects bone to bone at a joint."],["Tendon","A fibrous cord that connects muscle to bone."],["Scoliosis","An abnormal lateral (side-to-side) curvature of the spine."],["Osteoporosis","A condition of progressive bone tissue loss that makes bones weak and fracture-prone."],["Skeletal muscles","Muscles attached to bones that produce voluntary body movements."],["Cardiac muscle","The involuntary striated muscle that forms the walls of the heart — beats ~100,000 times/day."],["Tendinitis","Inflammation of a tendon, usually from overuse or injury."],["Neurons","Nerve cells that transmit messages to and from the brain and spinal cord."],["Cerebrum","The largest part of the brain; center of conscious thought, learning, memory, and voluntary movement."],["Cerebellum","The part of the brain that coordinates skeletal muscle movement, balance, and posture."],["Brain stem","The stalk connecting the spinal cord to the rest of the brain; regulates vital involuntary functions."],["Epilepsy","A neurological disorder characterized by recurrent, unpredictable seizures."]]},"15":{"title":"Cardiovascular, Respiratory & Digestive Systems","terms":[["Plasma","The liquid portion of blood (~55%), carrying nutrients, proteins, hormones, and salts."],["Hemoglobin","The oxygen-carrying protein in red blood cells, containing iron."],["Platelets","Blood cell fragments that initiate clotting when a vessel is damaged."],["Capillaries","The smallest blood vessels; the site of gas and nutrient exchange between blood and cells."],["Blood pressure","The force blood exerts against artery walls as the heart pumps — measured in mmHg."],["Diaphragm","The dome-shaped muscle below the lungs that drives breathing."],["Trachea","The windpipe; carries air from the throat to the bronchi."],["Asthma","A chronic inflammatory condition in which airways narrow, causing difficulty breathing."],["Emphysema","A progressive, irreversible disease that destroys alveolar walls; almost always caused by smoking."],["Mastication","The mechanical process of chewing."],["Peristalsis","Rhythmic, involuntary muscle contractions that move food through the digestive tract."],["Nephrons","The microscopic filtering units of the kidney; each kidney has over one million."]]},"16":{"title":"Endocrine & Reproductive Health","terms":[["Endocrine glands","Ductless organs that release hormones directly into the bloodstream."],["Hormones","Chemical messengers that regulate body functions including growth, metabolism, mood, and reproduction."],["Thyroid gland","Neck gland that produces thyroxine, regulating metabolism, body heat, and bone growth."],["Pancreas","Dual-function organ that regulates blood sugar through insulin (lowers) and glucagon (raises)."],["Pituitary gland","The 'master gland' that regulates all other endocrine glands."],["Testosterone","The primary male sex hormone; drives puberty, muscle development, and sperm production."],["Testes","The two male reproductive glands that produce sperm and testosterone."],["Ovaries","The female reproductive glands that store ova and produce estrogen and progesterone."],["Ovulation","The monthly release of a mature egg from an ovary into the fallopian tube."],["Menstruation","The monthly shedding of the uterine lining when pregnancy has not occurred."],["Uterus","The hollow, muscular organ that nourishes and protects a developing fetus during pregnancy."],["Puberty","The biological process by which the body develops adult reproductive and secondary sex characteristics."]]},"17":{"title":"The Beginning of the Life Cycle","terms":[["Fertilization","The union of a sperm and egg cell, resulting in a zygote; also called conception."],["Implantation","The process by which the zygote attaches to and burrows into the uterine wall."],["Embryo","The developing organism from weeks 3–8 of pregnancy."],["Fetus","The developing organism from week 9 through birth."],["Prenatal care","The health practices and medical supervision a pregnant woman undertakes to protect her health and her baby's."],["Fetal Alcohol Spectrum Disorders","A range of permanent conditions caused by prenatal alcohol exposure — 100% preventable."],["Chromosomes","Thread-like structures in the cell nucleus that carry the genetic code; humans have 46 (23 pairs)."],["Genes","Segments of chromosomes that are the basic units of heredity; each codes for specific traits."],["DNA","The double-helix molecule that makes up chromosomes and contains the complete genetic code."],["Gene therapy","A medical treatment that corrects genetic disorders by introducing, repairing, or replacing defective genes."],["Developmental tasks","The milestones and experiences that must occur at each life stage for healthy growth."],["Autonomy","The growing confidence and ability to control one's own body and choices — key in early childhood."]]},"18":{"title":"The Life Cycle Continues","terms":[["Adolescence","The developmental period between childhood and adulthood, marked by puberty and significant changes."],["Cognition","The ability to reason, think abstractly, and arrive at solutions; develops significantly during adolescence."],["Prefrontal cortex","Brain region responsible for planning, reasoning, and impulse control — not fully mature until ~age 25."],["Physical maturity","The state at which the body and all its organs are fully developed."],["Emotional maturity","The state at which mental and emotional capabilities are fully developed."],["Commitment","A promise or pledge to another person; the foundation of marriage and other lasting partnerships."],["Transitions","Significant life changes that occur at all stages of life and require adjustment."],["Empty-nest syndrome","The feelings of sadness some parents experience when children grow up and leave home."],["Integrity","In late adulthood, the sense of having lived according to one's values and that the life has been meaningful."],["Menopause","The natural biological process marking the end of a woman's menstrual cycles, typically in the late 40s–50s."]]},"19":{"title":"Medicines & Drugs","terms":[["Medicines","Drugs used to treat, prevent, or manage diseases or other medical conditions."],["Drugs","Substances other than food that change the structure or function of the body or mind."],["Vaccine","A preparation that trains the immune system to recognize and fight a specific disease without causing it."],["Side effects","Effects of a medication other than the intended therapeutic effect."],["Prescription medicines","Medications dispensed only with written approval from a licensed prescriber."],["Over-the-counter medicines","Medications available without a prescription, approved for self-directed use when label is followed."],["Medicine misuse","Using a medication in ways other than intended — even without intent to abuse."],["Medicine abuse","Intentionally using a medication for non-medical reasons; illegal and dangerous."],["Drug overdose","A toxic, potentially fatal reaction when a drug is taken in an amount the body cannot safely process."],["Fentanyl","A synthetic opioid 50–100× more potent than morphine; now found in counterfeit pills — responsible for ~80% of teen overdose deaths."],["Naloxone","A medication (Narcan) that rapidly reverses opioid overdose — now available OTC without prescription."],["Synergistic effect","When two medicines together produce a greater combined effect than either alone — can be dangerous."]]},"20":{"title":"Tobacco","terms":[["Nicotine","The addictive stimulant drug found in all tobacco products and most e-cigarettes."],["Carcinogen","A cancer-causing substance; tobacco smoke contains at least 70 known carcinogens."],["Tar","The thick, sticky residue produced when tobacco burns; destroys cilia and alveoli."],["Carbon monoxide","A colorless, odorless poisonous gas in tobacco smoke that displaces oxygen in the blood."],["Leukoplakia","Thickened, white, leathery patches inside the mouth caused by smokeless tobacco use."],["Nicotine withdrawal","The physical and psychological symptoms that occur when a tobacco user stops using nicotine."],["Nicotine substitutes","Products (patches, gum, lozenges) that deliver controlled doses of nicotine to ease withdrawal."],["Environmental tobacco smoke","Air contaminated by tobacco smoke; also called secondhand smoke."],["Mainstream smoke","Smoke exhaled from a smoker's lungs."],["Sidestream smoke","Smoke from the burning end of a cigarette; contains higher concentrations of toxic substances."],["E-cigarettes","Electronic devices that heat a nicotine liquid to create an aerosol — NOT water vapor — also called vaping."]]},"21":{"title":"Alcohol","terms":[["Ethanol","The type of alcohol found in beverages; a powerful, addictive depressant drug."],["Depressant","A drug that slows the central nervous system — alcohol is a depressant."],["Intoxication","The state in which alcohol has significantly impaired a person's physical and mental control."],["Binge drinking","Consuming enough alcohol to reach a BAC of 0.08% or above within about 2 hours."],["Alcohol poisoning","A severe, potentially fatal physical reaction to alcohol overdose — requires immediate 911 response."],["Blood alcohol concentration","The percentage of alcohol in a person's blood — the standard measure of intoxication for driving."],["Psychological dependence","A condition in which a person believes they need alcohol to feel good or function normally."],["Physiological dependence","A condition in which the body has a chemical need for alcohol; stopping causes physical withdrawal."],["Alcohol use disorder","A chronic brain disease involving compulsive alcohol use despite devastating consequences."],["Fetal Alcohol Spectrum Disorders","A range of permanent conditions caused by alcohol exposure during pregnancy — leading preventable cause of intellectual disability."]]},"22":{"title":"Illegal Drugs","terms":[["Substance abuse","The unnecessary or improper use of chemical substances for non-medical purposes."],["Illegal drugs","Chemical substances that people of any age may not lawfully manufacture, possess, buy, or sell."],["Addiction","A chronic brain disease involving compulsive drug use despite devastating consequences."],["Marijuana","A plant whose dried leaves and flowers contain THC; legally variable by state but illegal for minors everywhere."],["Inhalants","Substances whose fumes are inhaled to produce intoxication; can cause sudden death even on first use."],["Anabolic steroids","Synthetic hormones similar to testosterone; non-medical use is illegal and causes serious health damage."],["Hallucinogens","Drugs that alter mood, thoughts, and sensory perceptions, causing hallucinations."],["Opiates","Drugs derived from or chemically similar to opium; highly effective pain relievers and highly addictive."],["Stimulants","Drugs that speed up central nervous system activity — cocaine, meth, amphetamines."],["Rehabilitation","The process of medical and psychological treatment for physiological or psychological dependence on a drug."],["Counterfeit pills","Pills made to look exactly like real prescriptions but containing fentanyl or other dangerous substances."]]},"23":{"title":"Communicable Diseases","terms":[["Communicable disease","A disease that spreads from one organism to another or through the environment."],["Infection","The condition that results when pathogens multiply in the body and damage cells."],["Vector","An organism (such as a mosquito or tick) that carries and transmits pathogens."],["Immune system","The body's network of cells, tissues, organs, and chemicals that fight pathogens."],["Antibody","A protein produced by B cells that targets a specific antigen, marking it for destruction."],["Vaccine","A preparation that stimulates the immune system to develop protection against a specific disease."],["Immunity","The state of being protected against a specific disease."],["Inflammatory response","The immune system's first response to tissue damage or infection."],["Pandemic","A global outbreak of an infectious disease — COVID-19 is the most recent major example."],["Epidemic","A disease outbreak that affects many people in the same place at the same time."],["Emerging infections","Communicable diseases whose occurrence in humans has increased significantly in recent decades."],["mRNA vaccine","A vaccine that uses genetic instructions to teach cells to make a harmless piece of a pathogen — COVID-19 type."]]},"24":{"title":"STIs & HIV/AIDS","terms":[["Sexually transmitted infection","An infection passed from person to person through sexual contact; also called STD."],["Asymptomatic","Showing no symptoms despite being infected — makes STIs especially dangerous."],["HPV","Human Papillomavirus — the most common STI; high-risk strains cause cancer. Prevented by Gardasil 9."],["Chlamydia","The most reported bacterial STI; mostly asymptomatic; curable with antibiotics; untreated causes infertility."],["Gonorrhea","The second most common bacterial STI; drug resistance is a growing crisis."],["Syphilis","Progresses through stages; congenital syphilis up 700% over the past decade; curable with penicillin."],["HIV","Human Immunodeficiency Virus — attacks CD4+ T cells, progressively destroying the immune system."],["AIDS","Acquired Immunodeficiency Syndrome — the final stage of HIV infection."],["Antiretroviral therapy","The combination of medications that suppress HIV replication — allows near-normal lifespan."],["U=U","Undetectable equals Untransmittable — people with HIV on effective ART cannot sexually transmit the virus."],["PrEP","Pre-Exposure Prophylaxis — reduces HIV transmission risk from sex by ~99% when taken as prescribed."],["Gardasil 9","The current HPV vaccine covering 9 strains — recommended for all people ages 9–26."]]},"25":{"title":"Noncommunicable Diseases & Disabilities","terms":[["Noncommunicable disease","A disease that cannot be spread from person to person."],["Cardiovascular disease","Any disease affecting the heart or blood vessels; the leading cause of death in the U.S."],["Hypertension","Chronically elevated blood pressure (130/80 or above per 2017 AHA guidelines); the 'silent killer'."],["Atherosclerosis","A disease in which fatty plaques accumulate on artery walls, narrowing and hardening them."],["Stroke","An acute injury in which blood flow to part of the brain is interrupted — requires immediate 911 response."],["Cancer","A disease characterized by the uncontrolled growth and spread of abnormal cells."],["Tumor","An abnormal mass of tissue; may be benign (non-cancerous) or malignant (cancerous)."],["Metastasis","The spread of cancer from its original location to other parts of the body."],["Remission","A period when cancer is undetectable or under control."],["Diabetes","A chronic disease in which the body cannot properly regulate blood glucose."],["Allergy","An immune system overreaction to a normally harmless substance (allergen)."],["Americans with Disabilities Act","The 1990 federal law prohibiting discrimination against people with disabilities."]]},"26":{"title":"Safety & Injury Prevention","terms":[["Personal safety","The steps you take to reduce your risk of becoming a victim of crime."],["Cyberbullying","The use of digital technology to harass, humiliate, or threaten — affects ~46% of teens."],["Accident chain","The predictable sequence: unsafe situation → unsafe habit → unsafe action = accident."],["Defensive driving","Driving with awareness of potential hazards and taking proactive action to avoid them."],["Road rage","Responding to driving incidents with aggression or violence."],["Graduated licensing","A staged system that increases driving privileges as new drivers build experience."],["Personal flotation device","A life jacket or other approved device that keeps a person afloat — required for boating."],["OSHA","The Occupational Safety and Health Administration — the federal agency responsible for workplace safety."],["Fire safety","Practices to prevent and respond to fires — smoke alarms, extinguishers, and escape plans."],["Distracted driving","Operating a vehicle while attention is diverted — texting is the most dangerous form."]]},"27":{"title":"First Aid & Emergencies","terms":[["First aid","The immediate, temporary care given to an ill or injured person until professional care arrives."],["Good Samaritan laws","Statutes that protect individuals who provide reasonable emergency care in good faith."],["Universal precautions","The practice of treating all blood and body fluids as potentially infectious."],["CPR","Cardiopulmonary Resuscitation — emergency procedure combining chest compressions and rescue breathing."],["Hands-Only CPR","Compression-only CPR — AHA-recommended for untrained bystanders responding to adult cardiac arrest."],["AED","Automated External Defibrillator — delivers electric shock to restore normal heart rhythm."],["Chain of survival","The sequence: Call 911 → CPR → AED → Advanced care → Post-arrest care."],["Shock","A life-threatening condition in which circulation is inadequate to supply oxygen to body tissues."],["Fracture","A break in a bone — requires immobilization and medical evaluation."],["Concussion","A jarring brain injury caused by a blow or jolt to the head — always warrants medical evaluation."],["P.R.I.C.E.","Protect, Rest, Ice, Compress, Elevate — the treatment protocol for sprains and strains."],["Emergency survival kit","A collection of supplies needed to sustain a household for 72+ hours during or after an emergency."]]},"28":{"title":"Community & Environmental Health","terms":[["Health care system","All the medical care available to a nation's people, the way they receive care, and the way they pay for it."],["Primary care physician","A medical doctor who provides physical checkups and general care."],["Public health","A community's effort to protect the health of all its people."],["Health insurance","Private and government programs that pay for part or all of a person's medical costs."],["Air pollution","Contamination of the atmosphere by harmful substances including gases and particulate matter."],["Smog","A form of air pollution created when sunlight reacts with vehicle and industrial emissions."],["Radon","A colorless, odorless radioactive gas from soil — the second leading cause of lung cancer in the U.S."],["EPA","The Environmental Protection Agency — the U.S. government agency responsible for environmental regulations."],["Water pollution","Contamination of water supplies by industrial waste, agricultural runoff, or sewage."],["Hazardous waste","Toxic, corrosive, or flammable materials that require special disposal to protect human health."],["Specialists","Medical doctors who focus on particular kinds of patients or particular medical conditions."],["Medical history","Complete and comprehensive information about your immunizations and any health problems you have had."]]}};
